setTimeout(() => {
        if (this.readyState !== 0) return;
        if (state === "online") {
          this.open();
          if ((this.readyState as number) === 1) options.onOpen?.(this);
        } else {
          // No session or no network: the handshake fails and never opens.
          this.finish(1006, "", false);
        }
      }, 0)

