      child.once("error", (e) => {
        clearTimeout(timer);
        reject(e);
      });
      child.once("exit", (code) => {
        clearTimeout(timer);
        reject(new Error(`fixture exited ${code}: ${stderr}`));
      });
      child.stdout!.on("data", (b) => {
        stdout += String(b);
        if (stdout.includes("\n")) {
          clearTimeout(timer);
          try {
            res(JSON.parse(stdout.split("\n")[0]).url);
          } catch (e) {
            reject(e);
          }
        }
      });
    })

